"<h1>Панель устройства</h1><p class='subtitle'>Состояние и управление вашей ESP32</p><section class='hero'><div><small>Добро пожаловать в Orbit</small><h2>Всё под контролем.</h2><p>Устройство работает в штатном режиме. Хорошего дня!</p></div><div class='hero-meta'><span>IP-АДРЕС УСТРОЙСТВА</span><strong id='heroIp'>0.0.0.0</strong></div></section>"
"<div class='grid stats'><article class='stat'><div class='stat-label'>Сигнал Wi-Fi <i class='stat-icon'>◉</i></div><div class='stat-value' id='wifiStat'>— dBm</div><div class='stat-note' id='wifiHint'>Ожидание данных</div></article><article class='stat'><div class='stat-label'>BLE-клиенты <i class='stat-icon'>ᛒ</i></div><div class='stat-value' id='bleStat'>0</div><div class='stat-note'>Подключено сейчас</div></article><article class='stat'><div class='stat-label'>Шум BLE · демо <i class='stat-icon'>⌁</i></div><div class='stat-value'><span id='noiseStat'>24</span><small style='font-size:11px'> / 100</small></div><div class='stat-note'>Смоделированный эфир</div></article><article class='stat'><div class='stat-label'>Версия прошивки <i class='stat-icon'>⌘</i></div><div class='stat-value' id='fwStat'>—</div><div class='stat-note'>Текущая сборка</div></article></div>"
"<div class='grid dash'><article class='card'><div class='card-head'><div><h3>Качество Wi-Fi</h3><p class='desc'>Реальный RSSI точки доступа</p></div><span class='tag'>LIVE</span></div><div class='gauge-wrap'><svg class='gauge' viewBox='0 0 100 100'><circle class='track' cx='50' cy='50' r='45'/><circle class='arc' id='wifiArc' cx='50' cy='50' r='45'/><text class='gauge-text' id='wifiGauge' x='50' y='49'>—</text><text class='gauge-unit' x='50' y='62'>dBm</text></svg><div class='legend'><span><i></i>Сигнал<strong id='wifiQuality'>Нет связи</strong></span><span><i class='orange'></i>Сеть<strong id='networkName'>—</strong></span></div></div></article>"
"<article class='card'><div class='card-head'><div><h3>BLE-эфир</h3><p class='desc'>Визуальная симуляция активности</p></div><span class='tag'>DEMO</span></div><div class='gauge-wrap'><svg class='gauge' viewBox='0 0 100 100'><circle class='track' cx='50' cy='50' r='45'/><circle class='arc' id='bleArc' cx='50' cy='50' r='45' style='stroke:#8e72f5'/><text class='gauge-text' id='bleGauge' x='50' y='49'>24</text><text class='gauge-unit' x='50' y='62'>ИНДЕКС</text></svg><div class='legend'><span><i style='background:#8e72f5'></i>Активность<strong id='bleActivity'>Низкая</strong></span><span><i class='orange'></i>Измерение<strong>Не выполняется</strong></span></div></div><svg class='spark' viewBox='0 0 260 48' preserveAspectRatio='none'><defs><linearGradient id='shade' x1='0' x2='0' y1='0' y2='1'><stop offset='0' stop-color='#8e72f5' stop-opacity='.2'/><stop offset='1' stop-color='#8e72f5' stop-opacity='0'/></linearGradient></defs><path class='fill' id='sparkFill' d='M0 45 L0 33 L24 28 L48 34 L72 19 L96 25 L120 12 L144 22 L168 14 L192 25 L216 11 L240 18 L260 8 L260 45 Z'/><path id='sparkLine' d='M0 33 L24 28 L48 34 L72 19 L96 25 L120 12 L144 22 L168 14 L192 25 L216 11 L240 18 L260 8'/></svg></article>"
"<article class='card'><div class='card-head'><div><h3>Память устройства</h3><p class='desc'>Свободная heap-память ESP32</p></div><span class='tag'>HEAP</span></div><div class='mem'><div><div class='memrow'><span>Свободно сейчас</span><b id='heapFree'>—</b></div><div class='bar'><i id='heapBar'></i></div></div><div class='memrow'><span>Минимум с запуска</span><b id='heapMin'>—</b></div><div class='memrow'><span>Крупнейший блок</span><b id='heapLargest'>—</b></div><div class='memrow'><span>HTML-страница во flash</span><b id='htmlBytes'>—</b></div></div><p class='note'>HTML хранится во flash; heap меняется при обработке HTTP-запросов.</p></article></div>"
"<section class='section' id='settings'><div class='section-head'><div><h2>Настройки</h2><p>Параметры устройства и интерфейса</p></div><span class='tag'>ПРОТОТИП</span></div><div class='grid columns'>"
"<article class='card setting'><div class='card-head'><div><h3>Потребление</h3><p class='desc'>Управление энергопотреблением</p></div><i class='stat-icon'>✦</i></div><div class='empty'>Настройки энергопотребления появятся здесь</div></article>"
"<article class='card setting' id='ble'><div class='card-head'><div><h3>Bluetooth LE</h3><p class='desc'>Имя устройства и состояние рекламы</p></div><i class='stat-icon'>ᛒ</i></div><div class='row'><label class='field'>Имя BLE-устройства<input class='input' id='bleName' maxlength='17' value='ESP32-NUS-Mock'></label><button class='btn secondary' onclick='saveBleName()'>Сохранить</button></div><div class='row'><div class='copy'><strong>Раздавать рекламу</strong><small>Демо-переключатель · состояние радио не меняется</small></div><label class='switch'><input id='advSwitch' type='checkbox' checked onchange='toast(\"Изменён только вид переключателя — радио не меняется\")'><span></span></label></div></article>"
"<article class='card setting' id='wifi'><div class='card-head'><div><h3>Wi-Fi</h3><p class='desc'>Известные сети · демонстрационный список</p></div><i class='stat-icon'>◉</i></div><div class='row'><div class='copy'><strong>Текущая сеть</strong><small id='wifiCurrent'>Определяется устройством…</small></div><span class='tag' id='wifiTag'>—</span></div><div class='wifi-list' id='wifiList'></div><button class='btn secondary' style='width:100%;margin-top:10px' onclick='openModal()'>＋ Добавить сеть</button><p class='note'>Список хранится только в браузере; данные ESP32 не меняются.</p></article>"
"<article class='card setting' id='algorithms'><div class='card-head'><div><h3>Алгоритмы</h3><p class='desc'>Пользовательские сценарии</p></div><i class='stat-icon'>⌘</i></div><div class='algorithm'><i>✦</i><div><strong>Пока всё спокойно</strong><p>Здесь появятся настройки алгоритмов обработки данных.</p></div></div></article></div></section>"
"<section class='section' id='firmware'><div class='section-head'><div><h2>Информация о прошивке</h2><p>Версия и OTA-обновление</p></div></div><div class='grid firmware'><article class='card'><div class='card-head'><div><h3>Установленная версия</h3><p class='desc'>Сведения из образа приложения</p></div><span class='tag'>ESP-IDF</span></div><div class='version'><i>✓</i><div><strong id='fwVersion'>—</strong><small>ESP32 Dev Module · 4 MB</small></div></div><div class='memrow'><span>Состояние устройства</span><b id='firmwareState'>Работает</b></div></article>"
"<article class='card'><div class='card-head'><div><h3>Обновление прошивки</h3><p class='desc'>Выберите OTA application .bin файл</p></div><i class='stat-icon'>⇧</i></div><div class='upload'><label class='field'>Файл прошивки<input class='input' type='file' id='otaFile' accept='.bin,application/octet-stream'></label><div class='upload-line'><label class='field'>OTA-пароль<input class='input' type='password' id='otaPassword' placeholder='Введите пароль'></label><button class='btn' onclick='uploadFirmware()'>Загрузить</button></div><progress class='progress' id='otaProgress' value='0' max='100' hidden></progress><p class='ota-status' id='otaStatus'>Пароль задаётся по Serial: SETOTAPASS &lt;пароль&gt;</p></div><p class='note'>Обновляйте прошивку только в доверенной сети.</p></article></div></section>"
"<footer class='footer'><span><b>orbit</b> · интерфейсный прототип для ESP32</span><span>Обновлено: <span id='lastUpdate'>—</span></span></footer></main>"
"<div class='toast' id='toast' role='status' aria-live='polite'></div><div class='backdrop' id='backdrop' onclick='if(event.target===this)closeModal()'><div class='modal' role='dialog' aria-modal='true'><h3>Добавить сеть</h3><p>Сеть будет добавлена в демо-список браузера. Пароль не сохраняется.</p><label class='field'>Название сети (SSID)<input class='input' id='newSsid' maxlength='32' placeholder='Например, Home Wi-Fi'></label><label class='field'>Пароль сети<input class='input' id='newPassword' type='password' placeholder='Не будет сохранён'></label><div class='actions'><button class='btn secondary' onclick='closeModal()'>Отмена</button><button class='btn' onclick='addWifi()'>Добавить в демо</button></div></div></div>"
"<script>"
"const $=id=>document.getElementById(id);let timer;"
"function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('toast').classList.remove('show'),2500)}"
"function bytes(n){return Number.isFinite(n)?(n>=1024?(n/1024).toFixed(1)+' KB':n+' B'):'—'}"
"function gauge(id,n){$(id).style.strokeDashoffset=(282.74*(1-Math.max(0,Math.min(100,n))/100)).toFixed(1)}"
"function quality(r){return r===null?'Нет связи':r>-55?'Отличный':r>-67?'Хороший':r>-75?'Средний':'Слабый'}"
"async function command(c){const r=await fetch('/api/cmd?c='+encodeURIComponent(c),{cache:'no-store'});return(await r.text()).trim()}"
"function wifiItems(){try{const x=JSON.parse(localStorage.getItem('orbit-demo-wifi')||'[]');return Array.isArray(x)?x.filter(y=>typeof y==='string'):[]}catch(e){return[]}}"
"function saveItems(x){try{localStorage.setItem('orbit-demo-wifi',JSON.stringify(x))}catch(e){toast('Браузер не разрешил сохранить список')}}"
"function renderWifi(){const root=$('wifiList');root.replaceChildren();const list=wifiItems();if(!list.length){const e=document.createElement('div');e.className='empty';e.textContent='Список пуст — добавьте сеть для демонстрации';root.append(e);return}list.forEach(ssid=>{const row=document.createElement('div');row.className='wifi-item';const icon=document.createElement('span');icon.className='wifi-symbol';icon.textContent='◉';const copy=document.createElement('div');copy.className='wifi-copy';const name=document.createElement('strong');name.textContent=ssid;const detail=document.createElement('small');detail.textContent=ssid===$('wifiCurrent').dataset.ssid?'Активная сеть устройства':'Демо-запись в браузере';copy.append(name,detail);const del=document.createElement('button');del.className='btn ghost';del.type='button';del.textContent='Забыть';del.onclick=()=>{saveItems(wifiItems().filter(x=>x!==ssid));renderWifi();toast('Сеть удалена из демо-списка')};row.append(icon,copy,del);root.append(row)})}"
"function openModal(){$('backdrop').classList.add('show');$('newSsid').focus()}function closeModal(){$('backdrop').classList.remove('show');$('newSsid').value='';$('newPassword').value=''}"
"function addWifi(){const s=$('newSsid').value.trim();if(!s){toast('Введите название сети');return}const list=wifiItems();if(list.includes(s)){toast('Эта сеть уже добавлена');return}list.push(s);saveItems(list);renderWifi();closeModal();toast('Сеть добавлена в демо-список')}"
"async function saveBleName(){const name=$('bleName').value.trim();if(!name||new TextEncoder().encode(name).length>17){toast('Имя должно занимать от 1 до 17 байт UTF-8');return}try{const r=await command('SETNAME'+name);toast(r.startsWith('OK')?'Имя BLE сохранено на устройстве':r)}catch(e){toast('Не удалось связаться с ESP32')}}"
"function initPidUi(){document.head.insertAdjacentHTML('beforeend',`<style>@media(min-width:1151px){.stats{grid-template-columns:repeat(5,minmax(0,1fr))}}@media(max-width:1150px) and (min-width:741px){.stats{grid-template-columns:repeat(3,minmax(0,1fr))}}.dash{grid-template-columns:repeat(2,minmax(0,1fr))}.pid-reading{margin:18px 0 2px;font-size:38px;font-weight:780;letter-spacing:-1.5px}.pid-reading small{font-size:15px;font-weight:600;letter-spacing:0;color:var(--muted)}.pid-meta{display:flex;justify-content:space-between;margin-top:12px;color:var(--muted);font-size:10px}.pid-settings{grid-column:span 2}.pid-fields{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:11px;margin-top:15px}.pid-actions{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-top:14px}.pid-progress{height:5px;margin-top:8px;overflow:hidden;border-radius:8px;background:#eef1f7}.pid-progress i{display:block;width:0;height:100%;background:linear-gradient(90deg,#586cf4,#8e72f5);transition:width .2s}@media(max-width:740px){.dash{grid-template-columns:1fr}.pid-settings{grid-column:auto}.pid-fields{grid-template-columns:1fr}.pid-actions{align-items:flex-start;flex-direction:column}}</style>`);document.querySelector('.stats').insertAdjacentHTML('beforeend',`<article class='stat'><div class='stat-label'>Показание PID <i class='stat-icon'>◉</i></div><div class='stat-value' id='pidStat'>— mV</div><div class='stat-note'>GPIO32 · аналоговый вход</div></article>`);document.querySelector('.dash').insertAdjacentHTML('beforeend',`<article class='card'><div class='card-head'><div><h3>PID-сенсор</h3><p class='desc'>Калиброванное аналоговое значение</p></div><span class='tag'>GPIO32 · ADC1</span></div><div class='pid-reading'><span id='pidValue'>—</span> <small>mV</small></div><div class='pid-progress'><i id='pidSampleBar'></i></div><div class='pid-meta'><span>Точки в текущем усреднении</span><strong id='pidSamples'>0 / 60</strong></div><p class='note'>Перед подключением проверьте, что выход датчика не превышает допустимое напряжение GPIO.</p></article>`);document.querySelector('.columns').insertAdjacentHTML('beforeend',`<article class='card setting pid-settings' id='pid'><div class='card-head'><div><h3>PID-сенсор</h3><p class='desc'>Калибровка и усреднение · настройки сохраняются в устройстве</p></div><span class='tag'>ADC1</span></div><div class='pid-fields'><label class='field'>Смещение, мВ<input class='input' id='pidOffset' type='number' min='0' max='999999' step='1'></label><label class='field'>Множитель<input class='input' id='pidAmp' type='number' min='0' max='999999' step='any'></label><label class='field'>Точек усреднения<input class='input' id='pidAvg' type='number' min='1' max='999999' step='1'></label></div><div class='pid-actions'><small class='muted' id='pidConfigStatus'>Формула: (ADC mV + смещение) × множитель</small><button class='btn' type='button' onclick='savePid()'>Сохранить калибровку</button></div></article>`);document.querySelector('.version small').id='hwVersion';document.querySelector('.nav').insertAdjacentHTML('beforeend',`<a href='#pid'><b>◉</b>PID-сенсор</a>`)}"
"async function savePid(){const offset=Number($('pidOffset').value);const multiplier=Number($('pidAmp').value);const points=Number($('pidAvg').value);if(!Number.isInteger(offset)||offset<0||offset>999999||!Number.isFinite(multiplier)||multiplier<0||multiplier>999999||!Number.isInteger(points)||points<1||points>999999){toast('Проверьте значения: смещение и множитель 0..999999, усреднение 1..999999');return}try{for(const text of ['SETOFSETPID'+offset,'SETAMPPID'+multiplier,'SETAVGPIONTSPID'+points]){const result=await command(text);if(!result.startsWith('OK'))throw Error(result)}$('pidConfigStatus').textContent='Сохранено · формула: (ADC mV + смещение) × множитель';toast('Настройки PID сохранены в памяти устройства');refreshPid()}catch(e){$('pidConfigStatus').textContent=String(e.message||e);toast('Не удалось сохранить настройки PID')}}"
"async function refreshPid(){try{const r=await fetch('/api/status',{cache:'no-store'});if(!r.ok)throw Error();const d=await r.json();$('hwVersion').textContent='ESP32 Dev Module · 4 MB · HW '+d.hw;$('fwStat').closest('.stat').querySelector('.stat-note').textContent='HW '+d.hw;$('pidStat').textContent=d.pid_ready?d.pid_mv.toLocaleString('ru-RU')+' mV':'— mV';$('pidValue').textContent=d.pid_ready?d.pid_mv.toLocaleString('ru-RU'):'Ожидание';$('pidSamples').textContent=d.pid_samples.toLocaleString('ru-RU')+' / '+d.pid_avg_points.toLocaleString('ru-RU');$('pidSampleBar').style.width=Math.min(100,d.pid_samples*100/d.pid_avg_points)+'%';if(!$('pidOffset').dataset.loaded){$('pidOffset').value=d.pid_offset_mv;$('pidAmp').value=d.pid_multiplier;$('pidAvg').value=d.pid_avg_points;$('pidOffset').dataset.loaded='1'}}catch(e){}}"
"async function refresh(){try{const r=await fetch('/api/status',{cache:'no-store'});if(!r.ok)throw Error();const d=await r.json();$('heroIp').textContent=d.ip;$('sideIp').textContent=d.ip==='0.0.0.0'?'Wi-Fi не подключён':d.ip;$('fwStat').textContent=d.fw;$('fwVersion').textContent='v'+d.fw;$('bleStat').textContent=d.ble_clients;const connected=!!d.wifi_connected;const rssi=connected?d.wifi_rssi:null;$('wifiStat').textContent=rssi===null?'— dBm':rssi+' dBm';$('wifiGauge').textContent=rssi===null?'—':rssi;$('wifiHint').textContent=connected?quality(rssi)+' сигнал':'Wi-Fi не подключён';$('wifiQuality').textContent=quality(rssi);$('networkName').textContent=connected?$('wifiCurrent').dataset.ssid||'Подключена':'Нет сети';$('wifiTag').textContent=connected?'ПОДКЛЮЧЕНО':'OFFLINE';$('wifiCurrent').textContent=connected?$('wifiCurrent').dataset.ssid||'Сеть активна':'Нет подключения';gauge('wifiArc',connected?Math.max(0,Math.min(100,Math.round((rssi+100)*100/60))):0);$('heapFree').textContent=bytes(d.heap_free);$('heapMin').textContent=bytes(d.heap_min);$('heapLargest').textContent=bytes(d.heap_largest);$('htmlBytes').textContent=bytes(d.html_bytes);$('heapBar').style.width=Math.max(2,Math.min(100,d.heap_free*100/200000))+'%';$('firmwareState').textContent=connected?'Работает · Wi-Fi онлайн':'Работает · автономно';$('lastUpdate').textContent=new Date().toLocaleTimeString('ru-RU');"
"if(!$('bleName').dataset.loaded){try{const desc=await command('GETADVDESC');const m=desc.match(/RSP name=\\[([^\\]]*)\\]/);if(m)$('bleName').value=m[1];$('bleName').dataset.loaded='1'}catch(e){}}"
"if(!$('wifiCurrent').dataset.loaded){try{const response=await command('GETWIFISSID');const m=response.match(/^SSID: \\[([\\s\\S]*)\\]$/);if(m&&m[1]){$('wifiCurrent').dataset.ssid=m[1];const list=wifiItems();if(!list.includes(m[1])){list.unshift(m[1]);saveItems(list)}}$('wifiCurrent').dataset.loaded='1';renderWifi()}catch(e){}}"
"$('connection').textContent='На связи'}catch(e){$('connection').textContent='Нет связи';$('firmwareState').textContent='Устройство недоступно';$('wifiHint').textContent='Нет данных от устройства'}}"
"async function uploadFirmware(){const file=$('otaFile').files[0];const password=$('otaPassword').value;const status=$('otaStatus');const progress=$('otaProgress');if(!file){status.textContent='Сначала выберите application .bin файл.';return}if(!password){status.textContent='Введите OTA-пароль.';return}if(!confirm('Установить '+file.name+' и перезагрузить устройство?'))return;const x=new XMLHttpRequest();x.open('POST','/api/ota');x.setRequestHeader('Content-Type','application/octet-stream');x.setRequestHeader('X-OTA-Password',password);x.upload.onload=()=>status.textContent='Файл передан, ожидается проверка устройством…';x.onload=()=>status.textContent=x.responseText;x.onerror=()=>status.textContent='Ошибка передачи: проверьте соединение';status.textContent='Начинаем загрузку…';progress.hidden=false;progress.value=0;x.send(file)}"
"async function refreshOta(){try{const r=await fetch('/api/ota/status',{cache:'no-store'});if(!r.ok)return;const d=await r.json();if(d.total>0){$('otaProgress').hidden=false;$('otaProgress').value=d.written*100/d.total}if(d.active)$('otaStatus').textContent=d.stage+' · '+Math.floor(d.written*100/d.total)+'% записано во flash';else if(d.stage==='Failed')$('otaStatus').textContent='Ошибка OTA: '+d.message;else if(d.stage==='Restarting')$('otaStatus').textContent='Обновление установлено. Устройство перезагружается.'}catch(e){}}"
"function animate(){const n=Math.round(17+Math.random()*22);$('noiseStat').textContent=n;$('bleGauge').textContent=n;gauge('bleArc',n);$('bleActivity').textContent=n<30?'Низкая':n<55?'Умеренная':'Повышенная';const p=Array.from({length:14},(_,i)=>`${i*20},${34-Math.random()*22}`).join(' L');$('sparkLine').setAttribute('d','M'+p);$('sparkFill').setAttribute('d','M0 45 L'+p+' L260 45 Z')}"
"document.querySelectorAll('.nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelectorAll('.nav a').forEach(x=>x.classList.remove('active'));a.classList.add('active')}));document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});initPidUi();renderWifi();refresh();refreshPid();refreshOta();animate();setInterval(refresh,3000);setInterval(refreshPid,3000);setInterval(refreshOta,1000);setInterval(animate,3500);"
"</script></body></html>";
